{"cards": [{"node_code": "N_9e6bd0a89b2288f1", "definition": "规定机车检修范围、周期、技术标准、作业流程及验收规范的制度性文件与技术准则，涵盖不同等级检修（如小修、中修、大修）的具体要求。", "boundary": "本节点聚焦于“规程”与“标准”本身，即指导检修工作的规范性文件。边界在于区分“规程”与“具体作业”：具体的拆装、调试操作归入“机务设备及检修作业”或特定机车检修节点；机务段的人员排班、物资管理归入“机务段工作组织及管理”。若内容涉及规程的制定原理或历史演变，仍归本节点。", "includes": ["机车各级检修（小、中、大、辅修）的技术标准与周期规定", "检修作业流程、安全规范及质量验收标准", "检修记录、台账管理及技术档案管理规范"], "excludes": ["具体的机械拆装、电气调试等实操技术（归入机务设备及检修作业或特定机车检修）", "机务段行政、人事、财务等综合管理内容（归入机务段工作组织及管理）"], "sibling_distinctions": [{"other_code": "N_ed2a5c25db75e4e4", "rule": "区分依据为内容性质：本节点侧重“规定”与“标准”（做什么、做到什么程度）；兄弟节点侧重“执行”与“方法”（怎么做、用什么设备做）。"}, {"other_code": "N_88b0f19ae9f02f0b", "rule": "区分依据为管理对象：本节点侧重技术层面的检修标准；兄弟节点侧重组织层面的人员、流程与资源管理。"}], "cross_boundary_rule": "若内容同时包含检修标准与具体实施案例，若侧重标准解读归本节点，侧重实操细节归机务设备及检修作业。"}, {"node_code": "N_88b0f19ae9f02f0b", "definition": "研究机务段作为机车维修与运用基地的组织架构、人员配置、生产计划、物资供应、成本控制及安全管理等综合管理理论与实践。", "boundary": "本节点聚焦于机务段的“管理”职能，包括行政、人事、计划与资源调度。边界在于区分“管理”与“技术”：具体的检修工艺、设备操作归入“机务设备及检修作业”或特定机车检修；检修技术标准归入“机务检修规程”。若涉及机务段与调度所的接口协调，侧重内部组织归本节点。", "includes": ["机务段组织机构设置、岗位职责及人员培训管理", "机车检修生产计划编制、进度控制及绩效考核", "机务段物资采购、库存管理、成本控制及安全生产管理"], "excludes": ["具体的机车检修技术工艺与操作规范（归入机务设备及检修作业或特定机车检修）", "机车运行中的操纵、调度指挥（归入机车操纵与运用）"], "sibling_distinctions": [{"other_code": "N_9e6bd0a89b2288f1", "rule": "区分依据为管理维度：本节点侧重组织、计划与资源管理；兄弟节点侧重技术标准与规范。"}, {"other_code": "N_ed2a5c25db75e4e4", "rule": "区分依据为职能性质：本节点侧重管理决策与流程优化；兄弟节点侧重现场作业执行与设备使用。"}], "cross_boundary_rule": "若内容涉及“检修计划管理”，若侧重计划编制逻辑与资源分配归本节点，若侧重计划执行中的技术调整归机务设备及检修作业。"}, {"node_code": "N_ed2a5c25db75e4e4", "definition": "研究机务段内用于机车检修的专用设备、工装夹具、检测仪器，以及具体的检修作业方法、工艺流程、故障诊断技术与现场操作规范。", "boundary": "本节点聚焦于检修现场的“设备”与“作业”技术。边界在于区分“设备/作业”与“规程/管理”：检修标准归“机务检修规程”，人员与计划管理归“机务段工作组织及管理”。若涉及特定类型机车（如电力机车）的专用检修技术，可关联至特定机车检修节点，但通用检修设备与通用作业方法归本节点。", "includes": ["机车检修专用台架、起重设备、检测仪器及工装夹具", "机车各系统（走行部、制动、电气等）的通用检修工艺与操作技术", "机车故障诊断方法、维修作业现场管理及安全防护技术"], "excludes": ["机车检修的技术标准与周期规定（归入机务检修规程）", "机务段行政、人事及生产计划管理（归入机务段工作组织及管理）"], "sibling_distinctions": [{"other_code": "N_9e6bd0a89b2288f1", "rule": "区分依据为内容性质：本节点侧重“怎么做”（设备使用、操作方法）；兄弟节点侧重“做什么”（标准、规范、周期）。"}, {"other_code": "N_88b0f19ae9f02f0b", "rule": "区分依据为职能性质：本节点侧重现场技术执行与设备应用；兄弟节点侧重后台管理与资源协调。"}], "cross_boundary_rule": "若内容涉及“检修设备的设计”，若侧重设备在检修作业中的应用与操作归本节点，若侧重设备本身的机械/电气设计原理，视树中是否有通用机械/电气节点而定，若无则保留在本节点作为检修专用工具。"}]}
